(6226359, 919791, 114896, '<td valign="top">wonderful abstract with great colors.</td>', 'wonderful abstract with great colors.', '2010-11-17 19:57:45.000000', NULL, 1),
(6226361, 920187, 114896, '<td valign="top">Wow is that clear. So nice to see the whole bird. It looks like he''s looking at himself.</td>', 'Wow is that clear. So nice to see the whole bird. It looks like he''s looking at himself.', '2010-11-17 19:58:19.000000', NULL, 1),
