(6227689, 920431, 114225, '<td valign="top">I very much enjoy the colors in this photo, and how the river leads your eyes.</td>', 'I very much enjoy the colors in this photo, and how the river leads your eyes.', '2010-11-19 10:02:13.000000', NULL, 1),
(6227692, 920227, 114225, '<td valign="top">Nice idea for the photo, but for me, it falls short. I think it''s mainly that the composition isn''t very interesting. Maybe try looking down the river to add some lines and perspective to the shot.</td>', 'Nice idea for the photo, but for me, it falls short. I think it''s mainly that the composition isn''t very interesting. Maybe try looking down the river to add some lines and perspective to the shot.', '2010-11-19 10:04:01.000000', NULL, 1),
(6227693, 920310, 114225, '<td valign="top">Great idea for the photo. Unfortunately, that extremely blown out background is taking a lot away from the image, in my opinion.</td>', 'Great idea for the photo. Unfortunately, that extremely blown out background is taking a lot away from the image, in my opinion.', '2010-11-19 10:05:13.000000', NULL, 1),
