(6232020, 920460, 122892, '<td valign="top">Thanks everyone that voted on my photo.</td>', 'Thanks everyone that voted on my photo.', '2010-11-24 08:46:37.000000', NULL, 0),
(6232036, 919970, 88235, '<td valign="top">I really liked this picture... For some reason it must have been offensive to some as you got a lot of 1''s 2''s and 3''s that you didn''t deserve.</td>', 'I really liked this picture... For some reason it must have been offensive to some as you got a lot of 1''s 2''s and 3''s that you didn''t deserve.', '2010-11-24 09:12:24.000000', NULL, 0),
(6232050, 920354, 61961, '<td valign="top">Scrolling through the challenge results, this one really made me stop and look.  Completely baffling.  I thought it was water reflecting the trees until I noticed the symmetrical "bubbles."  Then I saw the scratches and thought those were an overlay.  Finally upon reading your comments the image makes sense.  Lovely treatment.  A really unique and beautiful abstract.</td>', 'Scrolling through the challenge results, this one really made me stop and look.  Completely baffling.  I thought it was water reflecting the trees until I noticed the symmetrical "bubbles."  Then I saw the scratches and thought those were an overlay.  Finally upon reading your comments the image makes sense.  Lovely treatment.  A really unique and beautiful abstract.', '2010-11-24 09:36:18.000000', NULL, 0),
(6232056, 919409, 61961, '<td valign="top">Ooh, very nice!  How did you not score higher?  (Not that 35th is poor.)  I really like this.</td>', 'Ooh, very nice!  How did you not score higher?  (Not that 35th is poor.)  I really like this.', '2010-11-24 09:44:59.000000', NULL, 0),
